css:
.print-format{
    margin:5px;
    padding:6px;
}

th, td , table{
        font-size:12px;
        line-height:13px;

}


body{
   margin:6px;
}

/* Table header styling */
table th {
  background-color: #f2f2f2;
  border: 1px solid #000;
  padding: 8px;
  text-align: left;
}

/* Table footer styling */
table tfoot td {
  background-color: #f2f2f2;
  border: 1px solid #000;
  padding: 8px;
  text-align: right;
}

/* General table styling */
table {
  width: 100%;
  border-collapse: collapse;
}

/* Prevent page breaks inside earnings and deductions tables */
.earnings-table, .deductions-table {
  page-break-inside: avoid;
}
